package com.simibubi.create.test;

import com.mojang.blaze3d.platform.InputConstants;
import com.simibubi.create.*;
import com.simibubi.create.content.logistics.chute.*;
import com.simibubi.create.foundation.blockEntity.behaviour.FilterAmountScreen;
import com.simibubi.create.foundation.blockEntity.behaviour.filtering.FilteringSettings;
import java.util.concurrent.atomic.*;
import net.fabricmc.fabric.api.client.gametest.v1.context.*;
import net.minecraft.core.*;
import net.minecraft.world.item.*;
import net.minecraft.world.phys.*;

final class ChuteRenderingTest {
    private static final BlockPos P=new BlockPos(1110,5,5),WINDOW=P.east(4);
    static void run(ClientGameTestContext context,TestSingleplayerContext world){
        var server=world.getServer();var hidden=new AtomicBoolean();context.runOnClient(client->{hidden.set(client.gui.hud.isHidden());if(hidden.get())client.gui.hud.toggle();});server.runCommand("gamemode spectator @p");server.runCommand("tp @p 1110 8 12");context.waitFor(client->Math.abs(client.player.getX()-1110.5)<.1&&client.level.isLoaded(P),300);server.runCommand("fill 1105 3 0 1128 3 14 minecraft:smooth_quartz");
        server.runCommand("setblock 1110 6 5 minecraft:chest");server.runCommand("setblock 1110 5 5 create:smart_chute[powered=false]");server.runCommand("setblock 1110 4 5 minecraft:stone");server.runCommand("setblock 1114 5 5 create:chute[shape=window]");server.runCommand("setblock 1114 4 5 minecraft:stone");server.runCommand("setblock 1118 5 5 create:chute");server.runCommand("setblock 1119 6 5 create:chute[facing=east,shape=intersection]");server.runCommand("setblock 1119 7 5 create:chute[facing=east,shape=normal]");
        server.runCommand("gamemode survival @p");server.runCommand("tp @p 1110 4 8");server.runCommand("item replace entity @p weapon.mainhand with minecraft:apple 8");context.waitFor(client->!client.player.isSpectator()&&client.player.getMainHandItem().is(Items.APPLE)&&client.level.getBlockEntity(P) instanceof SmartChuteBlockEntity,200);
        lookFilter(context);context.getInput().pressKey(options->options.keyUse);context.waitFor(client->((SmartChuteBlockEntity)client.level.getBlockEntity(P)).filtering.getFilter().is(Items.APPLE),200);context.runOnClient(client->{if(client.player.getMainHandItem().getCount()!=8)throw new AssertionError("Smart chute sample consumed apples");});
        open(context);var point=coordinate(context,1,9);context.getInput().setCursorPos(point.x,point.y);context.waitTicks(3);context.takeScreenshot("create-vulkan-smart-chute-amount-board");context.getInput().releaseKey(options->options.keyUse);context.waitFor(client->client.gui.screen()==null&&((SmartChuteBlockEntity)client.level.getBlockEntity(P)).filtering.count==9&&!((SmartChuteBlockEntity)client.level.getBlockEntity(P)).filtering.upTo,200);
        open(context);context.getInput().pressKey(InputConstants.KEY_ESCAPE);context.getInput().releaseKey(options->options.keyUse);context.waitFor(client->client.gui.screen()==null,200);context.runOnClient(client->{if(((SmartChuteBlockEntity)client.level.getBlockEntity(P)).filtering.count!=9)throw new AssertionError("Escape changed chute amount");});
        server.runOnServer(ignored->{var level=world.getConnection().getServerLevel();((ChuteBlockEntity)level.getBlockEntity(WINDOW)).setItem(new ItemStack(Items.DIAMOND,7),.5f);((SmartChuteBlockEntity)level.getBlockEntity(P)).setItem(new ItemStack(Items.APPLE,9),-.5f);});
        context.waitFor(client->client.level.getBlockEntity(WINDOW) instanceof ChuteBlockEntity chute&&chute.getItem().is(Items.DIAMOND),200);context.runOnClient(client->{var state=client.getBlockEntityRenderDispatcher().tryExtractRenderState(client.level.getBlockEntity(WINDOW),.5f,null,true);if(!(state instanceof ChuteRenderer.State rendered)||rendered.item.isEmpty())throw new AssertionError("Window chute item extraction missing");var particle=client.particleEngine.createParticle(new com.simibubi.create.foundation.particle.AirParticleData(2,.1f),1114.5,4.5,5.5,0,1.5,0);if(!(particle instanceof com.simibubi.create.foundation.particle.AirParticle air)||air.getLifetime()<=0)throw new AssertionError("Native airflow particle provider missing");});
        server.runCommand("gamemode spectator @p");server.runCommand("tp @p 1117 8 12");context.waitFor(client->Math.abs(client.player.getX()-1117.5)<.1,200);context.getInput().lookAt(new BlockPos(1117,5,5));world.getConnection().waitForChunksRender();context.runOnClient(client->client.gui.hud.getChat().clearMessages(false));context.takeScreenshot("create-vulkan-chutes-window-and-diagonal");
        var reload=context.computeOnClient(client->client.reloadResourcePacks());context.waitFor(client->reload.isDone()&&client.gui.overlay()==null,600);context.runOnClient(client->{var rendered=client.getBlockEntityRenderDispatcher().tryExtractRenderState(client.level.getBlockEntity(WINDOW),.5f,null,true);if(!(rendered instanceof ChuteRenderer.State state)||state.item.isEmpty())throw new AssertionError("Chute item lost after resource reload");});
        // Drive actual upward suction under a top-mounted fan.
        server.runCommand("setblock 1123 4 5 create:depot");server.runCommand("setblock 1123 6 5 create:chute[shape=window]");server.runCommand("setblock 1123 7 5 create:chute[shape=window]");server.runCommand("setblock 1123 8 5 create:encased_fan[facing=down]");server.runCommand("setblock 1123 9 5 create:creative_motor[facing=down]");
        server.runOnServer(ignored->{var level=world.getConnection().getServerLevel();((com.simibubi.create.content.kinetics.base.KineticBlockEntity)level.getBlockEntity(new BlockPos(1123,9,5))).setGeneratedSpeed(-128);var depot=(com.simibubi.create.content.logistics.depot.DepotBlockEntity)level.getBlockEntity(new BlockPos(1123,4,5));try(var tx=net.fabricmc.fabric.api.transfer.v1.transaction.Transaction.openOuter()){depot.inventory.automation.insert(net.fabricmc.fabric.api.transfer.v1.item.ItemVariant.of(Items.APPLE),13,tx);tx.commit();}});
        context.waitFor(client->client.level.getBlockEntity(new BlockPos(1123,7,5)) instanceof ChuteBlockEntity chute&&chute.getItem().getCount()==13&&chute.getPull()==128,400);context.getInput().lookAt(new BlockPos(1123,6,5));world.getConnection().waitForChunksRender();context.takeScreenshot("create-vulkan-chutes-upward-airflow");
        chunkUnload(context,world);context.runOnClient(client->{if(client.gui.hud.isHidden()!=hidden.get())client.gui.hud.toggle();});
    }
    private static void chunkUnload(ClientGameTestContext context,TestSingleplayerContext world){
        var server=world.getServer();var lower=new BlockPos(1167,5,5);var upper=lower.above().east();server.runCommand("tp @p 1167 8 10");context.waitFor(client->Math.abs(client.player.getX()-1167.5)<.1&&client.level.isLoaded(upper),300);server.runCommand("setblock 1167 4 5 minecraft:stone");server.runCommand("setblock 1167 5 5 create:chute[shape=intersection]");server.runCommand("setblock 1168 6 5 create:chute[facing=east,shape=intersection]");server.runCommand("setblock 1168 7 5 create:encased_fan[facing=down]");
        server.runOnServer(ignored->{var level=world.getConnection().getServerLevel();var fan=(com.simibubi.create.content.kinetics.fan.EncasedFanBlockEntity)level.getBlockEntity(upper.above());fan.setNetworkState(128,128,false,new com.simibubi.create.content.kinetics.KineticGraph.Stress(10000,0,false),java.util.Map.of());var chute=(ChuteBlockEntity)level.getBlockEntity(lower);chute.setItem(new ItemStack(Items.DIAMOND,11),.5f);chute.requestAirflowUpdate();chute.refreshAirflow();level.getChunkSource().addTicket(new net.minecraft.server.level.Ticket(net.minecraft.server.level.TicketType.FORCED,33),new net.minecraft.world.level.ChunkPos(1167>>4,0));});
        server.runCommand("tp @p 5000 10 5000");var unloaded=new AtomicBoolean();for(int i=0;i<120&&!unloaded.get();i++){context.waitTicks(5);server.runOnServer(ignored->{var level=world.getConnection().getServerLevel();var chute=(ChuteBlockEntity)com.simibubi.create.foundation.utility.LoadedLevelAccess.blockEntity(level,lower);if(chute!=null){chute.requestAirflowUpdate();chute.refreshAirflow();}unloaded.set(!level.isLoaded(upper));});}if(!unloaded.get())throw new AssertionError("Chute airflow scan kept diagonal chunk loaded");
        server.runOnServer(ignored->{var level=world.getConnection().getServerLevel();var chute=(ChuteBlockEntity)com.simibubi.create.foundation.utility.LoadedLevelAccess.blockEntity(level,lower);for(int i=0;i<100;i++){chute.requestAirflowUpdate();chute.refreshAirflow();}if(chute.getPull()!=0||chute.getItem().getCount()!=11||level.isLoaded(upper))throw new AssertionError("Unloaded fan left phantom airflow or lost cargo");});
        server.runCommand("tp @p 1167 8 10");context.waitFor(client->Math.abs(client.player.getX()-1167.5)<.1&&client.level.getBlockEntity(lower) instanceof ChuteBlockEntity chute&&chute.getItem().getCount()==11,400);server.runOnServer(ignored->world.getConnection().getServerLevel().getChunkSource().removeTicketWithRadius(net.minecraft.server.level.TicketType.FORCED,new net.minecraft.world.level.ChunkPos(1167>>4,0),0));
    }
    private static void lookFilter(ClientGameTestContext context){var rotation=context.computeOnClient(client->{var target=SmartChuteBlock.filterPosition(Direction.SOUTH).add(Vec3.atLowerCornerOf(P));var delta=target.subtract(client.player.getEyePosition());return new Vec2((float)Math.toDegrees(Math.atan2(-delta.x,delta.z)),(float)-Math.toDegrees(Math.atan2(delta.y,Math.hypot(delta.x,delta.z))));});context.getInput().lookAt(rotation.x,rotation.y);context.waitFor(client->client.hitResult instanceof BlockHitResult hit&&hit.getBlockPos().equals(P)&&FilteringSettings.testHit(client.level.getBlockState(P),P,hit),200);}
    private static void open(ClientGameTestContext context){lookFilter(context);context.getInput().holdKey(options->options.keyUse);context.waitFor(client->client.gui.screen() instanceof FilterAmountScreen,200);}
    private static Vec2 coordinate(ClientGameTestContext context,int row,int amount){return context.computeOnClient(client->{var point=((FilterAmountScreen)client.gui.screen()).getCoordinateOfValue(row,amount);float scaleX=(float)client.getWindow().getScreenWidth()/client.getWindow().getGuiScaledWidth();float scaleY=(float)client.getWindow().getScreenHeight()/client.getWindow().getGuiScaledHeight();return new Vec2(point.x*scaleX,point.y*scaleY);});}
}
